class MinHeap {
  constructor() { this.heap = []; }
  push(val) {
    this.heap.push(val);
    let i = this.heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.heap[p] <= this.heap[i]) break;
      [this.heap[p], this.heap[i]] = [this.heap[i], this.heap[p]];
      i = p;
    }
  }
  pop() {
    const top = this.heap[0];
    this.heap[0] = this.heap.pop();
    let i = 0;
    while (true) {
      const l = 2 * i + 1, r = 2 * i + 2;
      let smallest = i;
      if (l < this.heap.length && this.heap[l] < this.heap[smallest]) smallest = l;
      if (r < this.heap.length && this.heap[r] < this.heap[smallest]) smallest = r;
      if (smallest === i) break;
      [this.heap[i], this.heap[smallest]] = [this.heap[smallest], this.heap[i]];
      i = smallest;
    }
    return top;
  }
  peek() { return this.heap[0]; }
  get size() { return this.heap.length; }
}
function KthLargest(k, nums) {
  this.k = k; this.heap = new MinHeap();
  for (const n of nums) { this.heap.push(n); if (this.heap.size > k) this.heap.pop(); }
}
KthLargest.prototype.add = function(val) {
  this.heap.push(val);
  if (this.heap.size > this.k) this.heap.pop();
  return this.heap.peek();
};

solution.cpp:
class KthLargest {
public:
    priority_queue<int, vector<int>, greater<int>> minHeap;
    int k;
    KthLargest(int k, vector<int>& nums) : k(k) {
        for (int n : nums) { minHeap.push(n); if (minHeap.size() > k) minHeap.pop(); }
    }
    int add(int val) {
        minHeap.push(val);
        if (minHeap.size() > k) minHeap.pop();
        return minHeap.top();
    }
};
